function escapeHtml(str: string): string {
  return String(str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

export function renderAuthBladePage(
  key: 'login' | 'register' | 'forgot' | 'reset',
  opts?: { error?: string | null; status?: string | null; email?: string | null; token?: string | null }
): string {
  let html = AUTH_BLADE_TEMPLATES[key] || AUTH_BLADE_TEMPLATES.login;
  const errHtml = opts?.error
    ? `<div class="gt-alert gt-alert-err" role="alert"><span>${escapeHtml(opts.error)}</span><button type="button" class="gt-alert-close-btn" onclick="this.parentElement.remove()" title="Fechar aviso">&times;</button></div>`
    : '';
  const statusHtml = opts?.status
    ? `<div class="gt-alert gt-alert-ok" role="status"><span>${escapeHtml(opts.status)}</span><button type="button" class="gt-alert-close-btn" onclick="this.parentElement.remove()" title="Fechar aviso">&times;</button></div>`
    : '';
  return html
    .replace('<!--__GT_ALERT_STATUS__-->', statusHtml)
    .replace('<!--__GT_ALERT_ERROR__-->', errHtml)
    .replace(/<!--__GT_EMAIL_VAL__-->/g, escapeHtml(opts?.email || ''))
    .replace(/<!--__GT_TOKEN_VAL__-->/g, escapeHtml(opts?.token || ''));
}
